  apply (nested_overflow_lift tm Cc Cin3 lapin3_0RB1LA_1LC1RC_1RD0LA_1LC1RB p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (6 * j + 8), (cden [] [] j BB1_0RB1LA_1LC1RC_1RD0LA_1LC1RB).
      split; [lia|]. split; [| exact (gbo_0RB1LA_1LC1RC_1RD0LA_1LC1RB j)].
