               run_boot_0RB1LA_1LC1RC_1RD0LA_1LC1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_0RB1LA_1LC1RC_1RD0LA_1LC1RB p (pow2 j) (pow2 j));
