    split; [| exact (geo_0RB1LA_1LC1RC_1RD0LA_1LC1RB p j E)].
    rewrite (gxi3_0RB1LA_1LC1RC_1RD0LA_1LC1RB j).
    exact (srun_sound tm true true che_0RB1LA_1LC1RC_1RD0LA_1LC1RB BE0_0RB1LA_1LC1RC_1RD0LA_1LC1RB B1_0RB1LA_1LC1RC_1RD0LA_1LC1RB 6 12
