(** ** The lap *)

Lemma lap_0RB1LA_1LC1RC_1RD0LA_1LC1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
