Lemma lapi_0RB1LA_1LC1RD_0RD0LC_0LA1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  pose proof (Nat.div_mod_eq j 2) as Hd.
  pose proof (Nat.mod_upper_bound j 2 ltac:(discriminate)) as Hm.
  set (i := j / 2) in *. set (r := j mod 2) in *. clearbody i r.
  destruct r as [|[|r]]; [idtac | idtac | exfalso; lia].
  - destruct i as [|i].
    + assert (Ej : j = 0) by lia. subst j.
      destruct (gpar1_0RB1LA_1LC1RD_0RD0LC_0LA1RB p q0 E) as (HA & HB).
      exists (0 * 0 + 4). split; [lia|]. rewrite HA.
      rewrite (srun_sound tm false true chp1_0RB1LA_1LC1RD_0RD0LC_0LA1RB P1_0RB1LA_1LC1RD_0RD0LC_0LA1RB0 P1_0RB1LA_1LC1RD_0RD0LC_0LA1RB1 0 4
                 run_p1_0RB1LA_1LC1RD_0RD0LC_0LA1RB (Kp q0 ++ [S0]) [] 0 ltac:(discriminate) ltac:(reflexivity)).
      f_equal. exact HB.
    + destruct (gpar0_0RB1LA_1LC1RD_0RD0LC_0LA1RB p j q0 i E ltac:(lia)) as (HA & HB).
      exists (8 * i + 12). split; [lia|]. rewrite HA.
      rewrite (srun_sound tm false true chp0_0RB1LA_1LC1RD_0RD0LC_0LA1RB P0_0RB1LA_1LC1RD_0RD0LC_0LA1RB0 P0_0RB1LA_1LC1RD_0RD0LC_0LA1RB1 8 12
                 run_p0_0RB1LA_1LC1RD_0RD0LC_0LA1RB (Kp q0 ++ [S0]) [] i ltac:(discriminate) ltac:(reflexivity)).
      f_equal. exact HB.
  - destruct (gpar2_0RB1LA_1LC1RD_0RD0LC_0LA1RB p j q0 i E ltac:(lia)) as (HA & HB).
    exists (4 * i + 4). split; [lia|]. rewrite HA.
    rewrite (srun_sound tm false true chp2_0RB1LA_1LC1RD_0RD0LC_0LA1RB P2_0RB1LA_1LC1RD_0RD0LC_0LA1RB0 P2_0RB1LA_1LC1RD_0RD0LC_0LA1RB1 4 4
               run_p2_0RB1LA_1LC1RD_0RD0LC_0LA1RB (Kp q0 ++ [S0]) [] i ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

