(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB1LA_1LC1RD_1LA1LC_1RB0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S1;S0]) [] j A0_0RB1LA_1LC1RD_1LA1LC_1RB0LA.
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (H1 & _).
  unfold Cc_0RB1LA_1LC1RD_1LA1LC_1RB0LA, cden, A0_0RB1LA_1LC1RD_1LA1LC_1RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_0RB1LA_1LC1RD_1LA1LC_1RB0LA : forall p j q0, cview p = (j, Some q0) ->
  cden (Jp q0 ++ [S1;S0]) [] j A1_0RB1LA_1LC1RD_1LA1LC_1RB0LA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (_ & H2).
  unfold Cc_0RB1LA_1LC1RD_1LA1LC_1RB0LA, cden, A1_0RB1LA_1LC1RD_1LA1LC_1RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LA_1LC1RD_1LA1LC_1RB0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 4). split; [lia|].
  rewrite (gsi_0RB1LA_1LC1RD_1LA1LC_1RB0LA p j q0 E).
  rewrite (srun_sound tm false true chi_0RB1LA_1LC1RD_1LA1LC_1RB0LA A0_0RB1LA_1LC1RD_1LA1LC_1RB0LA A1_0RB1LA_1LC1RD_1LA1LC_1RB0LA 4 4
             run_int_0RB1LA_1LC1RD_1LA1LC_1RB0LA (Jp q0 ++ [S1;S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_0RB1LA_1LC1RD_1LA1LC_1RB0LA p j q0 E).
Qed.

