Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1LA_1LC1RD_1LA1LC_1RB0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LA_1LC1RD_1LA1LC_1RB0LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1LA_1LC1RD_1LA1LC_1RB0LA
             = (StA, (rep [S1;S1] (S j) ++ [S1;S1], S0, []))).
