  intro j.
  assert (HD : cden [] [] j BB1_0RB1LA_1LC1RD_1LA1LC_1RB0LA = (StA, (((rep [S1;S1] j ++ [S1]) ++ [S0]) ++ [S0], S0, []))).
  { unfold cden, BB1_0RB1LA_1LC1RD_1LA1LC_1RB0LA, sden;
