(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB1LA_1LC1RD_1LA1LC_1RB0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB1LA_1LC1RD_1LA1LC_1RB0LA p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LA_1LC1RD_1LA1LC_1RB0LA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1LA_1LC1RD_1LA1LC_1RB0LA p (pow2 j)).
  - exists (4 * j + 4), (cden [] [] j BB1_0RB1LA_1LC1RD_1LA1LC_1RB0LA).
    split; [lia|]. split; [| exact (gbo_0RB1LA_1LC1RD_1LA1LC_1RB0LA j)].
    rewrite (gso_0RB1LA_1LC1RD_1LA1LC_1RB0LA p j E).
    exact (srun_sound tm true true chb_0RB1LA_1LC1RD_1LA1LC_1RB0LA B0_0RB1LA_1LC1RD_1LA1LC_1RB0LA BB1_0RB1LA_1LC1RD_1LA1LC_1RB0LA 4 4
             run_boot_0RB1LA_1LC1RD_1LA1LC_1RB0LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 7), (cden [] [] j B1_0RB1LA_1LC1RD_1LA1LC_1RB0LA).
    split; [| exact (geo_0RB1LA_1LC1RD_1LA1LC_1RB0LA p j E)].
    rewrite (gxi_0RB1LA_1LC1RD_1LA1LC_1RB0LA j).
