    vm_compute; reflexivity.
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB1LA_1LC1RD_1RA1LC_1RB0LA (StC, S0)).
    intros p1 j1 E1.
    exact (firex_0RB1LA_1LC1RD_1RA1LC_1RB0LA [SRotL 1; SWin 1; SCycL 2 0; SWinL 4; SCycR 2; SWin 1] (StC, S0) ltac:(vm_compute; reflexivity)
