  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB1LA_1LC1RD_1RA1LC_1RB0LA (StC, S1)).
    intros p1 j1 E1.
    exact (firex_0RB1LA_1LC1RD_1RA1LC_1RB0LA [SRotL 1; SWin 1; SCycL 2 0; SWinL 3] (StC, S1) ltac:(vm_compute; reflexivity)
