(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB1LA_1LC1RD_1RB0LA_1LB1RC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_111_101_1 q0 ++ [S0;S1;S0]) [] j A0_0RB1LA_1LC1RD_1RB0LA_1LB1RC.
Proof.
  intros p j q0 E. destruct (Alph_111_101_1.cview_some_Alph_111_101_1 p j q0 E) as (H1 & _).
  unfold Cc_0RB1LA_1LC1RD_1RB0LA_1LB1RC, cden, A0_0RB1LA_1LC1RD_1RB0LA_1LB1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_0RB1LA_1LC1RD_1RB0LA_1LB1RC : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_111_101_1 q0 ++ [S0;S1;S0]) [] j A1_0RB1LA_1LC1RD_1RB0LA_1LB1RC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_111_101_1.cview_some_Alph_111_101_1 p j q0 E) as (_ & H2).
  unfold Cc_0RB1LA_1LC1RD_1RB0LA_1LB1RC, cden, A1_0RB1LA_1LC1RD_1RB0LA_1LB1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LA_1LC1RD_1RB0LA_1LB1RC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (6 * j + 6), (cden (Ap_Alph_111_101_1 q0 ++ [S0;S1;S0]) [] j A1_0RB1LA_1LC1RD_1RB0LA_1LB1RC).
  split; [lia|]. split; [| exact (gei_0RB1LA_1LC1RD_1RB0LA_1LB1RC p j q0 E)].
  rewrite (gsi_0RB1LA_1LC1RD_1RB0LA_1LB1RC p j q0 E).
  exact (srun_sound tm false true chi_0RB1LA_1LC1RD_1RB0LA_1LB1RC A0_0RB1LA_1LC1RD_1RB0LA_1LB1RC A1_0RB1LA_1LC1RD_1RB0LA_1LB1RC 6 6
           run_int_0RB1LA_1LC1RD_1RB0LA_1LB1RC (Ap_Alph_111_101_1 q0 ++ [S0;S1;S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB1LA_1LC1RD_1RB0LA_1LB1RC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LA_1LC1RD_1RB0LA_1LB1RC.
Proof.
  intros p j E. destruct (Alph_111_101_1.cview_none_Alph_111_101_1 p j E) as (H1 & _).
