      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWinL 4]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtrm_0RB1LA_1LC1RD_1RB1RD_1RC0LA : NeverQuasiHaltsTr tmm_0RB1LA_1LC1RD_1RB1RD_1RC0LA.
Proof.
  apply (glue_neverqhtr tmm_0RB1LA_1LC1RD_1RB1RD_1RC0LA pins_0RB1LA_1LC1RD_1RB1RD_1RC0LA Cc 2).
