(** ** The lap *)

Lemma lap_0RB1LA_1RC0LA_0LD1RB_1LA1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LA_1RC0LA_0LD1RB_1LA1LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LA_1RC0LA_0LD1RB_1LA1LD B0_0RB1LA_1RC0LA_0LD1RB_1LA1LD B1_0RB1LA_1RC0LA_0LD1RB_1LA1LD 4 11 p j' [] []).
    + exact run_ovf_0RB1LA_1RC0LA_0LD1RB_1LA1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LA_1RC0LA_0LD1RB_1LA1LD p j' E).
    + exact (geo_0RB1LA_1RC0LA_0LD1RB_1LA1LD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LA_1RC0LA_0LD1RB_1LA1LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 8.
  assert (H : match csteps tm 8 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 8 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1LA_1RC0LA_0LD1RB_1LA1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LA_1RC0LA_0LD1RB_1LA1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1LA_1RC0LA_0LD1RB_1LA1LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LA_1RC0LA_0LD1RB_1LA1LD p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_0RB1LA_1RC0LA_0LD1RB_1LA1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_0RB1LA_1RC0LA_0LD1RB_1LA1LD = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
