Lemma gei_0RB1LA_1RC0LA_0LD1RB_1LA1RD : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Jp q0 ++ [S0]) [] j A1_0RB1LA_1RC0LA_0LD1RB_1LA1RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (_ & H2).
  unfold Cc_0RB1LA_1RC0LA_0LD1RB_1LA1RD, cden, A1_0RB1LA_1RC0LA_0LD1RB_1LA1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LA_1RC0LA_0LD1RB_1LA1RD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (4 * j + 8), (cden (Jp q0 ++ [S0]) [] j A1_0RB1LA_1RC0LA_0LD1RB_1LA1RD).
  split; [lia|]. split; [| exact (gei_0RB1LA_1RC0LA_0LD1RB_1LA1RD p j q0 E)].
  rewrite (gsi_0RB1LA_1RC0LA_0LD1RB_1LA1RD p j q0 E).
  exact (srun_sound tm false true chi_0RB1LA_1RC0LA_0LD1RB_1LA1RD A0_0RB1LA_1RC0LA_0LD1RB_1LA1RD A1_0RB1LA_1RC0LA_0LD1RB_1LA1RD 4 8
           run_int_0RB1LA_1RC0LA_0LD1RB_1LA1RD (Jp q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB1LA_1RC0LA_0LD1RB_1LA1RD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LA_1RC0LA_0LD1RB_1LA1RD.
