(** ** The lap *)

Lemma lap_0RB1LA_1RC0LA_0LD1RB_1LA1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LA_1RC0LA_0LD1RB_1LA1RD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LA_1RC0LA_0LD1RB_1LA1RD B0_0RB1LA_1RC0LA_0LD1RB_1LA1RD B1_0RB1LA_1RC0LA_0LD1RB_1LA1RD 4 12 p j' [] []).
    + exact run_ovf_0RB1LA_1RC0LA_0LD1RB_1LA1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LA_1RC0LA_0LD1RB_1LA1RD p j' E).
    + exact (geo_0RB1LA_1RC0LA_0LD1RB_1LA1RD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LA_1RC0LA_0LD1RB_1LA1RD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 9.
  assert (H : match csteps tm 9 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 9 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1LA_1RC0LA_0LD1RB_1LA1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LA_1RC0LA_0LD1RB_1LA1RD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1LA_1RC0LA_0LD1RB_1LA1RD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LA_1RC0LA_0LD1RB_1LA1RD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1LA_1RC0LA_0LD1RB_1LA1RD : forall t, ~ In t pins_0RB1LA_1RC0LA_0LD1RB_1LA1RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_0RB1LA_1RC0LA_0LD1RB_1LA1RD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1RC0LA_0LD1RB_1LA1RD [SCycL 2 0; SWin 2; SWinL 6; SCycR 2; SWinR 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1RC0LA_0LD1RB_1LA1RD [SCycL 2 0; SWin 2; SWinL 4] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
