(** ** The lap *)

Lemma lap_0RB1LA_1RC0LA_0LD1RB_1LB1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
