  - destruct (lapi_0RB1LA_1RC0LA_0LD1RB_1LB1RD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LA_1RC0LA_0LD1RB_1LB1RD B0_0RB1LA_1RC0LA_0LD1RB_1LB1RD B1_0RB1LA_1RC0LA_0LD1RB_1LB1RD 4 16 p j' [] []).
    + exact run_ovf_0RB1LA_1RC0LA_0LD1RB_1LB1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LA_1RC0LA_0LD1RB_1LB1RD p j' E).
    + exact (geo_0RB1LA_1RC0LA_0LD1RB_1LB1RD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LA_1RC0LA_0LD1RB_1LB1RD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
