Definition mk_0RB1LA_1RC0LA_0RD1RB_1LD1RA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB1LA_1RC0LA_0RD1RB_1LD1RA.

(** 0RB1LA_1RC0LA_0RD1RB_1LD1RA *)
(** 0RB1LA_1RC0LA_0RD1RB_1LD1RA -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB1LA_1RC0LA_0RD1RB_1LD1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S0 DL StA
  | StC, S0 => mk S0 DR StD | StC, S1 => mk S1 DR StB
  | StD, S0 => mk S1 DL StD | StD, S1 => mk S1 DR StA end.

(** Its mirror 0LB1RA_1LC0RA_0LD1LB_1RD1LA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB1LA_1RC0LA_0RD1RB_1LD1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DR StA
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S0 DR StA
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S1 DL StB
  | StD, S0 => mk S1 DR StD | StD, S1 => mk S1 DL StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LA_1RC0LA_0RD1RB_1LD1RA : list Instr := [].
Definition tmw_0RB1LA_1RC0LA_0RD1RB_1LD1RA : TM := tm_wrap_trs tmm_0RB1LA_1RC0LA_0RD1RB_1LD1RA pins_0RB1LA_1RC0LA_0RD1RB_1LD1RA.
