  split; [lia|]. split; [| exact (gei_0RB1LA_1RC0LA_0RD1RB_1LD1RA p j q0 E)].
  rewrite (gsi_0RB1LA_1RC0LA_0RD1RB_1LD1RA p j q0 E).
  exact (srun_sound tm false true chi_0RB1LA_1RC0LA_0RD1RB_1LD1RA A0_0RB1LA_1RC0LA_0RD1RB_1LD1RA A1_0RB1LA_1RC0LA_0RD1RB_1LD1RA 4 8
           run_int_0RB1LA_1RC0LA_0RD1RB_1LD1RA (Jp q0 ++ [S1;S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

