Lemma geo_0RB1LA_1RC0LA_0RD1RB_1LD1RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LA_1RC0LA_0RD1RB_1LD1RA) = lift (Cc (Pos.succ p)).
