    rewrite (gso_0RB1LA_1RC0LA_0RD1RB_1LD1RA p j E).
    exact (srun_sound tm true true chb_0RB1LA_1RC0LA_0RD1RB_1LD1RA B0_0RB1LA_1RC0LA_0RD1RB_1LD1RA BB1_0RB1LA_1RC0LA_0RD1RB_1LD1RA 4 8
             run_boot_0RB1LA_1RC0LA_0RD1RB_1LD1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 14), (cden [] [] j B1_0RB1LA_1RC0LA_0RD1RB_1LD1RA).
    split; [| exact (geo_0RB1LA_1RC0LA_0RD1RB_1LD1RA p j E)].
    rewrite (gxi_0RB1LA_1RC0LA_0RD1RB_1LD1RA j).
    exact (srun_sound tm true true che_0RB1LA_1RC0LA_0RD1RB_1LD1RA BE0_0RB1LA_1RC0LA_0RD1RB_1LD1RA B1_0RB1LA_1RC0LA_0RD1RB_1LD1RA 4 14
             run_exit_0RB1LA_1RC0LA_0RD1RB_1LD1RA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
