Lemma mirror_ok_0RB1LA_1RC0LA_1LA1RD_1RC0LA : mirror_tm tm_0RB1LA_1RC0LA_1LA1RD_1RC0LA = tmm_0RB1LA_1RC0LA_1LA1RD_1RC0LA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB1LA_1RC0LA_1LA1RD_1RC0LA (p : positive) : cconf := (StB, (Jp p ++ [S0], S0, [])).
