Proof. exact lapi_0RB1LA_1RC0LA_1LD1RB_1LA1LD. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LA_1RC0LA_1LD1RB_1LA1LD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1LA_1RC0LA_1LD1RB_1LA1LD p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_0RB1LA_1RC0LA_1LD1RB_1LA1LD).
    split; [lia|]. split; [| exact (gbo_0RB1LA_1RC0LA_1LD1RB_1LA1LD j)].
    rewrite (gso_0RB1LA_1RC0LA_1LD1RB_1LA1LD p j E).
    exact (srun_sound tm true true chb_0RB1LA_1RC0LA_1LD1RB_1LA1LD B0_0RB1LA_1RC0LA_1LD1RB_1LA1LD BB1_0RB1LA_1RC0LA_1LD1RB_1LA1LD 4 8
             run_boot_0RB1LA_1RC0LA_1LD1RB_1LA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 11), (cden [] [] j B1_0RB1LA_1RC0LA_1LD1RB_1LA1LD).
    split; [| exact (geo_0RB1LA_1RC0LA_1LD1RB_1LA1LD p j E)].
    rewrite (gxi_0RB1LA_1RC0LA_1LD1RB_1LA1LD j).
    exact (srun_sound tm true true che_0RB1LA_1RC0LA_1LD1RB_1LA1LD BE0_0RB1LA_1RC0LA_1LD1RB_1LA1LD B1_0RB1LA_1RC0LA_1LD1RB_1LA1LD 4 11
             run_exit_0RB1LA_1RC0LA_1LD1RB_1LA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_0RB1LA_1RC0LA_1LD1RB_1LA1LD : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_0RB1LA_1RC0LA_1LD1RB_1LA1LD = Some q ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ fst e = q.
Proof.
  intros l q Hst p j E.
  apply (vis_via_fill tm Cc Cin lapin_0RB1LA_1RC0LA_1LD1RB_1LA1LD q p (pow2 j)).
  - exists (4 * j + 8), (cden [] [] j BB1_0RB1LA_1RC0LA_1LD1RB_1LA1LD). split;
      [| exact (gbo_0RB1LA_1RC0LA_1LD1RB_1LA1LD j)].
    rewrite (gso_0RB1LA_1RC0LA_1LD1RB_1LA1LD p j E).
    exact (srun_sound tm true true chb_0RB1LA_1RC0LA_1LD1RB_1LA1LD B0_0RB1LA_1RC0LA_1LD1RB_1LA1LD BB1_0RB1LA_1RC0LA_1LD1RB_1LA1LD 4 8
             run_boot_0RB1LA_1RC0LA_1LD1RB_1LA1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (vis_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (vis_of_run tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB1LA_1RC0LA_1LD1RB_1LA1LD xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB1LA_1RC0LA_1LD1RB_1LA1LD j)].
Qed.



(** ** The lap *)

Lemma lap_0RB1LA_1RC0LA_1LD1RB_1LA1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LA_1RC0LA_1LD1RB_1LA1LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LA_1RC0LA_1LD1RB_1LA1LD p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LA_1RC0LA_1LD1RB_1LA1LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 8.
  assert (H : match csteps tm 8 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 8 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
