    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1LA_1RC0LA_1LD1RB_1LA1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LA_1RC0LA_1LD1RB_1LA1LD = Some t ->
  forall p j, cview p = (S j, None) ->
