    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LA_1RC0LA_1LD1RB_1LA1RD p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LA_1RC0LA_1LD1RB_1LA1RD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
