(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB1LA_1RC0LA_1RD0LA_1LA1RC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_0RB1LA_1RC0LA_1RD0LA_1LA1RC.
