  - destruct (lapi_0RB1LA_1RC0LA_1RD0LA_1LA1RC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LA_1RC0LA_1RD0LA_1LA1RC B0_0RB1LA_1RC0LA_1RD0LA_1LA1RC B1_0RB1LA_1RC0LA_1RD0LA_1LA1RC 4 18 p j' [] []).
    + exact run_ovf_0RB1LA_1RC0LA_1RD0LA_1LA1RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LA_1RC0LA_1RD0LA_1LA1RC p j' E).
    + exact (geo_0RB1LA_1RC0LA_1RD0LA_1LA1RC p j' E).
    + lia.
