Lemma fireo_0RB1LA_1RC0LA_1RD1RB_1LB1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LA_1RC0LA_1RD1RB_1LB1LC = Some t ->
