(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma firex_0RB1LA_1RC0LA_1RD1RB_1LB1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB1LA_1RC0LA_1RD1RB_1LB1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin (pow2 j))).
  { exists (4 * j + 12), (cden [] [] j BB1_0RB1LA_1RC0LA_1RD1RB_1LB1LC).
    split; [lia|]. split; [| exact (gbo_0RB1LA_1RC0LA_1RD1RB_1LB1LC j)].
    rewrite (gso_0RB1LA_1RC0LA_1RD1RB_1LB1LC p j E).
    exact (srun_sound tm true true chb_0RB1LA_1RC0LA_1RD1RB_1LB1LC B0_0RB1LA_1RC0LA_1RD1RB_1LB1LC BB1_0RB1LA_1RC0LA_1RD1RB_1LB1LC 4 12
             run_boot_0RB1LA_1RC0LA_1RD1RB_1LB1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_0RB1LA_1RC0LA_1RD1RB_1LB1LC p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (4 * j + 8), (cden [] [] j BM1_0RB1LA_1RC0LA_1RD1RB_1LB1LC).
    split; [| exact (gbo2_0RB1LA_1RC0LA_1RD1RB_1LB1LC j)].
    rewrite (gxi_0RB1LA_1RC0LA_1RD1RB_1LB1LC j).
    exact (srun_sound tm true true chm_0RB1LA_1RC0LA_1RD1RB_1LB1LC BM0_0RB1LA_1RC0LA_1RD1RB_1LB1LC BM1_0RB1LA_1RC0LA_1RD1RB_1LB1LC 4 8
             run_shift_0RB1LA_1RC0LA_1RD1RB_1LB1LC [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  destruct HB2 as (nB & cB & _ & HcB & HlB).
  apply (fire_via_fill tm Cc Cin2 lapin2_0RB1LA_1RC0LA_1RD1RB_1LB1LC t p (pow2 j));
    [exists nB, cB; exact (conj HcB HlB)|].
  apply (fire_lift_of_csteps tm (fun _ : positive => Cin2 (fill (pow2 j))) xH).
  apply (fire_of_run_instr tm (fun _ : positive => Cin2 (fill (pow2 j)))
                    true true l BE0_0RB1LA_1RC0LA_1RD1RB_1LB1LC xH j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gxi2_0RB1LA_1RC0LA_1RD1RB_1LB1LC j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1LA_1RC0LA_1RD1RB_1LB1LC : forall t, ~ In t pins_0RB1LA_1RC0LA_1RD1RB_1LB1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_0RB1LA_1RC0LA_1RD1RB_1LB1LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1RC0LA_1RD1RB_1LB1LC [SCycL 2 0; SWin 2; SWinL 6; SCycR 2; SWinR 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1RC0LA_1RD1RB_1LB1LC [SCycL 2 0; SWin 2; SWinL 4] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1RC0LA_1RD1RB_1LB1LC [] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1RC0LA_1RD1RB_1LB1LC [SCycL 2 0; SWin 2; SWinL 3] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1RC0LA_1RD1RB_1LB1LC [SCycL 2 0; SWin 2; SWinL 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1RC0LA_1RD1RB_1LB1LC [SCycL 2 0; SWin 1] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1RC0LA_1RD1RB_1LB1LC [SCycL 2 0; SWin 2; SWinL 2] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB1LA_1RC0LA_1RD1RB_1LB1LC (StD, S1)).
    intros p1 j1 E1.
    exact (firex_0RB1LA_1RC0LA_1RD1RB_1LB1LC [SCycL 2 0; SWin 4] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtrm_0RB1LA_1RC0LA_1RD1RB_1LB1LC : NeverQuasiHaltsTr tmm_0RB1LA_1RC0LA_1RD1RB_1LB1LC.
