Lemma mirror_ok_0RB1LA_1RC0LA_1RD1RB_1LD0LA : mirror_tm tm_0RB1LA_1RC0LA_1RD1RB_1LD0LA = tmm_0RB1LA_1RC0LA_1RD1RB_1LD0LA.
