Lemma geo_0RB1LA_1RC0LD_1LA1RB_0RB1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LA_1RC0LD_1LA1RB_0RB1LA) = lift (Cc (Pos.succ p)).
