(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB1LA_1RC1LB_0LB1RD_0LA0RC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_0RB1LA_1RC1LB_0LB1RD_0LA0RC.
