Definition mk_0RB1LA_1RC1RC_1LA1RD_1RB0LA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB1LA_1RC1RC_1LA1RD_1RB0LA.

(** 0RB1LA_1RC1RC_1LA1RD_1RB0LA *)
(** 0RB1LA_1RC1RC_1LA1RD_1RB0LA -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB1LA_1RC1RC_1LA1RD_1RB0LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DR StC
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S1 DR StB | StD, S1 => mk S0 DL StA end.

(** Its mirror 0LB1RA_1LC1LC_1RA1LD_1LB0RA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB1LA_1RC1RC_1LA1RD_1RB0LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S1 DR StA
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DL StC
  | StC, S0 => mk S1 DR StA | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S1 DL StB | StD, S1 => mk S0 DR StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB1LA_1RC1RC_1LA1RD_1RB0LA : list Instr := [].
Definition tmw_0RB1LA_1RC1RC_1LA1RD_1RB0LA : TM := tm_wrap_trs tmm_0RB1LA_1RC1RC_1LA1RD_1RB0LA pins_0RB1LA_1RC1RC_1LA1RD_1RB0LA.
Local Notation tm := tmw_0RB1LA_1RC1RC_1LA1RD_1RB0LA.

Lemma mirror_ok_0RB1LA_1RC1RC_1LA1RD_1RB0LA : mirror_tm tm_0RB1LA_1RC1RC_1LA1RD_1RB0LA = tmm_0RB1LA_1RC1RC_1LA1RD_1RB0LA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB1LA_1RC1RC_1LA1RD_1RB0LA (p : positive) : cconf := (StA, (Ap_Alph_111_101_1 p ++ [S0], S1, [])).
Local Notation Cc := Cc_0RB1LA_1RC1RC_1LA1RD_1RB0LA.

(** ** The certificate *)

Definition A0_0RB1LA_1RC1RC_1LA1RD_1RB0LA : sconf := mkC StA (mkS [] [S1;S0;S1] 1 0 [S1;S1;S1]) S1 (mkS [] [] 0 0 []).
Definition A1_0RB1LA_1RC1RC_1LA1RD_1RB0LA : sconf := mkC StA (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1]) S1 (mkS [S0] [] 0 0 []).
Definition chi_0RB1LA_1RC1RC_1LA1RD_1RB0LA : list lstep := [SWinR 2; SCycL 3 0; SWin 4; SCycR 3].

Lemma run_int_0RB1LA_1RC1RC_1LA1RD_1RB0LA : srun tm false true chi_0RB1LA_1RC1RC_1LA1RD_1RB0LA A0_0RB1LA_1RC1RC_1LA1RD_1RB0LA = Some (A1_0RB1LA_1RC1RC_1LA1RD_1RB0LA, 6, 6).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB1LA_1RC1RC_1LA1RD_1RB0LA : sconf := mkC StA (mkS [] [S1;S0;S1] 1 0 [S1;S0]) S1 (mkS [] [] 0 0 []).
Definition B1_0RB1LA_1RC1RC_1LA1RD_1RB0LA : sconf := mkC StA (mkS [] [S1;S1;S1] 1 1 [S1]) S1 (mkS [S0] [] 0 0 []).
Definition cho_0RB1LA_1RC1RC_1LA1RD_1RB0LA : list lstep := [SWinR 2; SCycL 3 0; SWin 2; SWinL 6; SCycR 3; SRotL 3; SFoldL 1].

Lemma run_ovf_0RB1LA_1RC1RC_1LA1RD_1RB0LA : srun tm true true cho_0RB1LA_1RC1RC_1LA1RD_1RB0LA B0_0RB1LA_1RC1RC_1LA1RD_1RB0LA = Some (B1_0RB1LA_1RC1RC_1LA1RD_1RB0LA, 6, 10).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB1LA_1RC1RC_1LA1RD_1RB0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_111_101_1 q0 ++ [S0]) [] j A0_0RB1LA_1RC1RC_1LA1RD_1RB0LA.
Proof.
  intros p j q0 E. destruct (Alph_111_101_1.cview_some_Alph_111_101_1 p j q0 E) as (H1 & _).
  unfold Cc_0RB1LA_1RC1RC_1LA1RD_1RB0LA, cden, A0_0RB1LA_1RC1RC_1LA1RD_1RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_0RB1LA_1RC1RC_1LA1RD_1RB0LA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_111_101_1 q0 ++ [S0]) [] j A1_0RB1LA_1RC1RC_1LA1RD_1RB0LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_111_101_1.cview_some_Alph_111_101_1 p j q0 E) as (_ & H2).
  unfold Cc_0RB1LA_1RC1RC_1LA1RD_1RB0LA, cden, A1_0RB1LA_1RC1RC_1LA1RD_1RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB1LA_1RC1RC_1LA1RD_1RB0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (6 * j + 6), (cden (Ap_Alph_111_101_1 q0 ++ [S0]) [] j A1_0RB1LA_1RC1RC_1LA1RD_1RB0LA).
  split; [lia|]. split; [| exact (gei_0RB1LA_1RC1RC_1LA1RD_1RB0LA p j q0 E)].
  rewrite (gsi_0RB1LA_1RC1RC_1LA1RD_1RB0LA p j q0 E).
  exact (srun_sound tm false true chi_0RB1LA_1RC1RC_1LA1RD_1RB0LA A0_0RB1LA_1RC1RC_1LA1RD_1RB0LA A1_0RB1LA_1RC1RC_1LA1RD_1RB0LA 6 6
           run_int_0RB1LA_1RC1RC_1LA1RD_1RB0LA (Ap_Alph_111_101_1 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB1LA_1RC1RC_1LA1RD_1RB0LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB1LA_1RC1RC_1LA1RD_1RB0LA.
Proof.
  intros p j E. destruct (Alph_111_101_1.cview_none_Alph_111_101_1 p j E) as (H1 & _).
  unfold Cc_0RB1LA_1RC1RC_1LA1RD_1RB0LA, cden, B0_0RB1LA_1RC1RC_1LA1RD_1RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB1LA_1RC1RC_1LA1RD_1RB0LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB1LA_1RC1RC_1LA1RD_1RB0LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB1LA_1RC1RC_1LA1RD_1RB0LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_111_101_1.cview_none_Alph_111_101_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB1LA_1RC1RC_1LA1RD_1RB0LA
             = (StA, (rep [S1;S1;S1] (S j) ++ [S1], S1, ([]) ++ [S0]))).
  { unfold cden, B1_0RB1LA_1RC1RC_1LA1RD_1RB0LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S1;S1;S1] (S j) ++ [S1]) ++ [S0], S1, []))).
  { unfold Cc_0RB1LA_1RC1RC_1LA1RD_1RB0LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_0RB1LA_1RC1RC_1LA1RD_1RB0LA. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_0RB1LA_1RC1RC_1LA1RD_1RB0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LA_1RC1RC_1LA1RD_1RB0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB1LA_1RC1RC_1LA1RD_1RB0LA B0_0RB1LA_1RC1RC_1LA1RD_1RB0LA B1_0RB1LA_1RC1RC_1LA1RD_1RB0LA 6 10 p j' [] []).
    + exact run_ovf_0RB1LA_1RC1RC_1LA1RD_1RB0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB1LA_1RC1RC_1LA1RD_1RB0LA p j' E).
    + exact (geo_0RB1LA_1RC1RC_1LA1RD_1RB0LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LA_1RC1RC_1LA1RD_1RB0LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 3.
  assert (H : match csteps tm 3 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 3 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1LA_1RC1RC_1LA1RD_1RB0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LA_1RC1RC_1LA1RD_1RB0LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1LA_1RC1RC_1LA1RD_1RB0LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LA_1RC1RC_1LA1RD_1RB0LA p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_0RB1LA_1RC1RC_1LA1RD_1RB0LA : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_0RB1LA_1RC1RC_1LA1RD_1RB0LA = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_0RB1LA_1RC1RC_1LA1RD_1RB0LA p j (Ap_Alph_111_101_1 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_0RB1LA_1RC1RC_1LA1RD_1RB0LA p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1LA_1RC1RC_1LA1RD_1RB0LA : forall t, ~ In t pins_0RB1LA_1RC1RC_1LA1RD_1RB0LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_0RB1LA_1RC1RC_1LA1RD_1RB0LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1RC1RC_1LA1RD_1RB0LA [SWinR 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1RC1RC_1LA1RD_1RB0LA [] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1RC1RC_1LA1RD_1RB0LA [SWinR 2; SCycL 3 0; SWin 2; SWinL 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1RC1RC_1LA1RD_1RB0LA [SWinR 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1RC1RC_1LA1RD_1RB0LA [SWinR 2; SCycL 3 0; SWin 2; SWinL 2] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1RC1RC_1LA1RD_1RB0LA [SWinR 2; SCycL 3 0; SWin 1] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB1LA_1RC1RC_1LA1RD_1RB0LA [SWinR 2; SCycL 3 0; SWin 2] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_0RB1LA_1RC1RC_1LA1RD_1RB0LA (StD, S1)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_0RB1LA_1RC1RC_1LA1RD_1RB0LA [SWinR 2; SCycL 3 0; SWin 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
Qed.

Theorem nqhtrm_0RB1LA_1RC1RC_1LA1RD_1RB0LA : NeverQuasiHaltsTr tmm_0RB1LA_1RC1RC_1LA1RD_1RB0LA.
Proof.
  apply (glue_neverqhtr tmm_0RB1LA_1RC1RC_1LA1RD_1RB0LA pins_0RB1LA_1RC1RC_1LA1RD_1RB0LA Cc 1).
  - exact boot_0RB1LA_1RC1RC_1LA1RD_1RB0LA.
  - intros p _. apply lap_0RB1LA_1RC1RC_1LA1RD_1RB0LA.
  - intros t Ht p _. apply fire_0RB1LA_1RC1RC_1LA1RD_1RB0LA. exact Ht.
Qed.

Theorem nqhtr_0RB1LA_1RC1RC_1LA1RD_1RB0LA : NeverQuasiHaltsTr tm_0RB1LA_1RC1RC_1LA1RD_1RB0LA.
Proof. apply (neverqhtr_mirror tm_0RB1LA_1RC1RC_1LA1RD_1RB0LA). rewrite mirror_ok_0RB1LA_1RC1RC_1LA1RD_1RB0LA. exact nqhtrm_0RB1LA_1RC1RC_1LA1RD_1RB0LA. Qed.

Theorem nonhalt_0RB1LA_1RC1RC_1LA1RD_1RB0LA : NonHalt tm_0RB1LA_1RC1RC_1LA1RD_1RB0LA.
Proof. apply never_qh_tr_nonhalt, nqhtr_0RB1LA_1RC1RC_1LA1RD_1RB0LA. Qed.

End LAPT_0RB1LA_1RC1RC_1LA1RD_1RB0LA.

Module LAPT_0RB1LA_1RC1RC_1RD0LA_1LA1RB.
(** * LAPT_0RB1LA_1RC1RC_1RD0LA_1LA1RB: TRANSITION-LEVEL board for machine 0RB1LA_1RC1RC_1RD0LA_1LA1RB, boarded by CERTIFICATE.

    Auto-emitted by tools/counters/emit_lapcert.py (UNTRUSTED emitter; the Coq
    kernel re-runs the checker on every line below).  Left-growth binary
    counter under the Ap_Alph_111_101_1 digit alphabet (Alph_111_101_1.v), anchored at

      Cc p = (StA, (Ap_Alph_111_101_1 p ++ [S1;S1;S0], S0, []))

    The lap is DATA, not a proof script: each branch is a list of steps for
    [Checkers/LapDecider.v], run by the kernel through [vm_compute] and
    discharged by the single theorem [srun_sound].

      interior  (cview p = (j, Some q0)):  6*j+4 steps
      overflow  (cview p = (S j, None)):   boot 6*j+4, then the inner counter's own laps to the
                                           all-ones fill, then exit 6*j+12

    The interior branch closes EXACTLY (which is what feeds
    [LapCertGlue.reach_ovf]); the overflow branch closes one blank short of
    the anchor tail, hence up to [lift].

    Differentially validated against the raw simulator on BOTH branches --
    step counts AND exact configurations -- for 192 interior anchors (interior); 6 overflow phases, j = 2..7 (246 inner laps) (nested overflow).
    Axiom footprint: [functional_extensionality_dep] (via [CTape.lift]). *)
Import Arith Lia Bool List PArith Wellfounded.
Import BBB4_Statement CTape Mirror.
Import FunctionalExtensionality.
Import WTape LapGlue LapGlueQH LapGlueAbs
                                  MonoCounter JpCounter Alph_111_101_1 LapCertGlue LapCertGlueLift IXPGadgets NestedLap NestedLapLift.
