      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB1LA_1RC1RC_1RD0LA_1LA1RB (StC, S0)).
    intros p1 j1 E1.
    exact (firex_0RB1LA_1RC1RC_1RD0LA_1LA1RB [SRotL 1; SWin 1; SCycL 3 0; SWin 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
