Definition tm_0RB1LA_1RC1RD_0LA1RC_1RB0LC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S0 DL StA | StC, S1 => mk S1 DR StC
