  exists (4 * i + 12), (cden (Jp q0 ++ [S1]) [] i AI1_0RB1LA_1RC1RD_1LA1LA_1RB0LC).
  split; [lia|]. split; [| exact (gen_0RB1LA_1RC1RD_1LA1LA_1RB0LC v i q0 E)].
  rewrite (gsn_0RB1LA_1RC1RD_1LA1LA_1RB0LC v i q0 E).
  exact (srun_sound tm false true chn_0RB1LA_1RC1RD_1LA1LA_1RB0LC AI0_0RB1LA_1RC1RD_1LA1LA_1RB0LC AI1_0RB1LA_1RC1RD_1LA1LA_1RB0LC 4 12
           run_inner_0RB1LA_1RC1RD_1LA1LA_1RB0LC (Jp q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_0RB1LA_1RC1RD_1LA1LA_1RB0LC : forall j, lift (cden [] [] j BB1_0RB1LA_1RC1RD_1LA1LA_1RB0LC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB1LA_1RC1RD_1LA1LA_1RB0LC = (StD, (rep [S1;S1] j ++ [S1;S1], S0, ([S1]) ++ [S0]))).
  { unfold cden, BB1_0RB1LA_1RC1RD_1LA1LA_1RB0LC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StD, (rep [S1;S1] j ++ [S1;S1], S0, [S1]))).
  { unfold Cin_0RB1LA_1RC1RD_1LA1LA_1RB0LC. rewrite epow2_0RB1LA_1RC1RD_1LA1LA_1RB0LC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB1LA_1RC1RD_1LA1LA_1RB0LC. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB1LA_1RC1RD_1LA1LA_1RB0LC : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB1LA_1RC1RD_1LA1LA_1RB0LC.
Proof.
  intro j.
  destruct (JpCounter.cview_none_J (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB1LA_1RC1RD_1LA1LA_1RB0LC, cden, BE0_0RB1LA_1RC1RD_1LA1LA_1RB0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB1LA_1RC1RD_1LA1LA_1RB0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB1LA_1RC1RD_1LA1LA_1RB0LC p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB1LA_1RC1RD_1LA1LA_1RB0LC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB1LA_1RC1RD_1LA1LA_1RB0LC p (pow2 j)).
  - exists (4 * j + 14), (cden [] [] j BB1_0RB1LA_1RC1RD_1LA1LA_1RB0LC).
    split; [lia|]. split; [| exact (gbo_0RB1LA_1RC1RD_1LA1LA_1RB0LC j)].
    rewrite (gso_0RB1LA_1RC1RD_1LA1LA_1RB0LC p j E).
    exact (srun_sound tm true true chb_0RB1LA_1RC1RD_1LA1LA_1RB0LC B0_0RB1LA_1RC1RD_1LA1LA_1RB0LC BB1_0RB1LA_1RC1RD_1LA1LA_1RB0LC 4 14
             run_boot_0RB1LA_1RC1RD_1LA1LA_1RB0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 6), (cden [] [] j B1_0RB1LA_1RC1RD_1LA1LA_1RB0LC).
    split; [| exact (geo_0RB1LA_1RC1RD_1LA1LA_1RB0LC p j E)].
    rewrite (gxi_0RB1LA_1RC1RD_1LA1LA_1RB0LC j).
    exact (srun_sound tm true true che_0RB1LA_1RC1RD_1LA1LA_1RB0LC BE0_0RB1LA_1RC1RD_1LA1LA_1RB0LC B1_0RB1LA_1RC1RD_1LA1LA_1RB0LC 4 6
             run_exit_0RB1LA_1RC1RD_1LA1LA_1RB0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB1LA_1RC1RD_1LA1LA_1RB0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB1LA_1RC1RD_1LA1LA_1RB0LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB1LA_1RC1RD_1LA1LA_1RB0LC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB1LA_1RC1RD_1LA1LA_1RB0LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 8.
  assert (H : match csteps tm 8 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 8 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB1LA_1RC1RD_1LA1LA_1RB0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB1LA_1RC1RD_1LA1LA_1RB0LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB1LA_1RC1RD_1LA1LA_1RB0LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB1LA_1RC1RD_1LA1LA_1RB0LC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB1LA_1RC1RD_1LA1LA_1RB0LC : forall t, ~ In t pins_0RB1LA_1RC1RD_1LA1LA_1RB0LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
